import os
from sys import stdout

# Board counts are generated by 1197_math_table.py from the eight legal jumps.
MOVES = (
    b"23444432",
    b"34666643",
    b"46888864",
    b"46888864",
    b"46888864",
    b"46888864",
    b"34666643",
    b"23444432",
)
FIRST_COLUMN = ord("a")
FIRST_ROW = ord("1")


def main():
    squares = open(0, "rb", buffering=0).read().split()
    for square in squares[1 : int(squares[0]) + 1]:
        print(chr(MOVES[square[0] - FIRST_COLUMN][square[1] - FIRST_ROW]))


main()
# Flush the answer before exiting without interpreter teardown.
stdout.flush()
os._exit(0)
